insert into app.questions(slug, skill_id, source_id, difficulty, statement, answer, justification, kind, payload, hints, misconception_tags, review_status, needs_professional_review) select 'pt.read.literal.2', (select id from app.skills where slug = 'pt.read.literal'), (select id from app.knowledge_sources limit 1), 0.4, 'Para onde Luna correu?', '{"correct":"b"}'::jsonb, '"Correu até a cozinha".', 'multiple_choice', '{"context":"A gata Luna dormia na janela, mas acordou com o barulho da chuva. Correu até a cozinha e ficou esperando o leite.","options":[{"id":"a","text":"Para o quarto","misconception":"pt_literal_skim"},{"id":"b","text":"Para a cozinha"},{"id":"c","text":"Para o jardim","misconception":"pt_literal_skim"},{"id":"d","text":"Para a rua","misconception":"pt_literal_skim"}],"correct":"b"}'::jsonb, '["Releia o fim do texto."]'::jsonb, '{pt_literal_skim}'::text[], 'draft', true;
insert into app.questions(slug, skill_id, source_id, difficulty, statement, answer, justification, kind, payload, hints, misconception_tags, review_status, needs_professional_review) select 'pt.read.infer.1', (select id from app.skills where slug = 'pt.read.infer'), (select id from app.knowledge_sources limit 1), 0.4, 'Pelo texto, o que provavelmente aconteceu com Lia no caminho?', '{"correct":"a"}'::jsonb, 'Tênis encharcados, cabelo pingando e guarda-chuva quebrado sugerem chuva forte.', 'multiple_choice', '{"context":"Lia chegou em casa com os tênis encharcados e o cabelo pingando. Deixou o guarda-chuva quebrado perto da porta.","options":[{"id":"a","text":"Pegou chuva forte"},{"id":"b","text":"Foi à praia","misconception":"pt_over_infer"},{"id":"c","text":"Ganhou um presente","misconception":"pt_over_infer"},{"id":"d","text":"Perdeu as chaves","misconception":"pt_over_infer"}],"correct":"a"}'::jsonb, '["Quais pistas mostram que ela se molhou?"]'::jsonb, '{pt_over_infer}'::text[], 'draft', true;
insert into app.questions(slug, skill_id, source_id, difficulty, statement, answer, justification, kind, payload, hints, misconception_tags, review_status, needs_professional_review) select 'pt.read.infer.2', (select id from app.skills where slug = 'pt.read.infer'), (select id from app.knowledge_sources limit 1), 0.6, 'Por que Lia deixou o guarda-chuva perto da porta?', '{"correct":"a"}'::jsonb, 'O guarda-chuva estava quebrado.', 'multiple_choice', '{"context":"Lia chegou em casa com os tênis encharcados e o cabelo pingando. Deixou o guarda-chuva quebrado perto da porta.","options":[{"id":"a","text":"Porque ele quebrou e não serviria mais"},{"id":"b","text":"Porque ela odeia guarda-chuvas","misconception":"pt_over_infer"},{"id":"c","text":"Porque o guarda-chuva era de outra pessoa","misconception":"pt_over_infer"},{"id":"d","text":"Porque estava sol","misconception":"pt_over_infer"}],"correct":"a"}'::jsonb, '["O que o texto diz sobre o estado do guarda-chuva?"]'::jsonb, '{pt_over_infer}'::text[], 'draft', true;
insert into app.questions(slug, skill_id, source_id, difficulty, statement, answer, justification, kind, payload, hints, misconception_tags, review_status, needs_professional_review) select 'pt.vocab.context.1', (select id from app.skills where slug = 'pt.vocab.context'), (select id from app.knowledge_sources limit 1), 0.4, 'Na frase "os tênis estavam encharcados", a palavra "encharcados" significa:', '{"correct":"a"}'::jsonb, '"Encharcado" = ensopado, muito molhado.', 'multiple_choice', '{"options":[{"id":"a","text":"muito molhados"},{"id":"b","text":"muito sujos"},{"id":"c","text":"muito velhos"},{"id":"d","text":"muito pequenos"}],"correct":"a"}'::jsonb, '["O que o texto diz sobre a chuva e o cabelo pingando?"]'::jsonb, '{}'::text[], 'draft', true;
insert into app.questions(slug, skill_id, source_id, difficulty, statement, answer, justification, kind, payload, hints, misconception_tags, review_status, needs_professional_review) select 'pt.gram.agree.1', (select id from app.skills where slug = 'pt.gram.agree'), (select id from app.knowledge_sources limit 1), 0.3, 'Qual frase está correta?', '{"correct":"a"}'::jsonb, 'Artigo, substantivo e adjetivo concordam: as casas pequenas.', 'multiple_choice', '{"options":[{"id":"a","text":"As casas pequenas ficam na rua."},{"id":"b","text":"As casa pequenas ficam na rua.","misconception":"pt_agree_noun"},{"id":"c","text":"As casas pequena ficam na rua.","misconception":"pt_agree_noun"},{"id":"d","text":"Os casas pequenas ficam na rua.","misconception":"pt_agree_noun"}],"correct":"a"}'::jsonb, '["Se \"casas\" está no plural feminino, o que acompanha também deve estar."]'::jsonb, '{pt_agree_noun}'::text[], 'draft', true;
insert into app.questions(slug, skill_id, source_id, difficulty, statement, answer, justification, kind, payload, hints, misconception_tags, review_status, needs_professional_review) select 'pt.gram.agree.2', (select id from app.skills where slug = 'pt.gram.agree'), (select id from app.knowledge_sources limit 1), 0.5, 'Complete: "___ menino__ alegre__ brincam."', '{"correct":"a"}'::jsonb, 'Masculino plural em todos os termos.', 'multiple_choice', '{"options":[{"id":"a","text":"Os meninos alegres"},{"id":"b","text":"O meninos alegres","misconception":"pt_agree_noun"},{"id":"c","text":"Os menino alegres","misconception":"pt_agree_noun"},{"id":"d","text":"Os meninos alegre","misconception":"pt_agree_noun"}],"correct":"a"}'::jsonb, '["Quantos meninos? Todos os termos acompanham."]'::jsonb, '{pt_agree_noun}'::text[], 'draft', true;
insert into app.questions(slug, skill_id, source_id, difficulty, statement, answer, justification, kind, payload, hints, misconception_tags, review_status, needs_professional_review) select 'pt.write.sentence.1', (select id from app.skills where slug = 'pt.write.sentence'), (select id from app.knowledge_sources limit 1), 0.3, 'Ordene as palavras para formar uma frase com sentido.', '{"correctOrder":["w1","w2","w3","w4"]}'::jsonb, '"O gato bebe leite."', 'ordering', '{"entries":[{"id":"w1","label":"O"},{"id":"w2","label":"gato"},{"id":"w3","label":"bebe"},{"id":"w4","label":"leite"}],"correctOrder":["w1","w2","w3","w4"]}'::jsonb, '["Quem faz a ação vem primeiro."]'::jsonb, '{}'::text[], 'draft', true;
insert into app.questions(slug, skill_id, source_id, difficulty, statement, answer, justification, kind, payload, hints, misconception_tags, review_status, needs_professional_review) select 'pt.spell.rules.1', (select id from app.skills where slug = 'pt.spell.rules'), (select id from app.knowledge_sources limit 1), 0.4, 'Qual palavra está escrita corretamente?', '{"correct":"a"}'::jsonb, '"passarinho" usa "ss" entre vogais.', 'multiple_choice', '{"options":[{"id":"a","text":"passarinho"},{"id":"b","text":"pasarinho"},{"id":"c","text":"paçarinho"},{"id":"d","text":"pasarinio"}],"correct":"a"}'::jsonb, '["Entre vogais, o som de \"s\" forte pede \"ss\"."]'::jsonb, '{}'::text[], 'draft', true;
insert into app.misconceptions(id, skill_id, label, category, description) select 'off_by_one', id, 'Erro de contagem por 1', 'occasional', 'Resposta próxima do correto (±1): costuma ser distração ou contagem, não conceito.' from app.skills where slug = 'add.facts';
insert into app.misconceptions(id, skill_id, label, category, description) select 'forgot_carry', id, 'Esqueceu de "levar" na adição', 'procedural', 'Somou coluna a coluna sem passar o excedente para a próxima ordem.' from app.skills where slug = 'add.carry';
insert into app.misconceptions(id, skill_id, label, category, description) select 'swap_operands', id, 'Inverteu os números na subtração', 'conceptual', 'Subtraiu o menor do maior independentemente da ordem.' from app.skills where slug = 'sub.facts';
insert into app.misconceptions(id, skill_id, label, category, description) select 'smaller_from_larger', id, 'Subtrai sempre o menor do maior em cada coluna', 'procedural', 'Quando o dígito de cima é menor, inverte em vez de reagrupar.' from app.skills where slug = 'sub.borrow';
insert into app.misconceptions(id, skill_id, label, category, description) select 'borrow_slip', id, 'Erro ao reagrupar (±10)', 'procedural', 'Reagrupou mas não ajustou a ordem vizinha.' from app.skills where slug = 'sub.borrow';
insert into app.misconceptions(id, skill_id, label, category, description) select 'add_instead_of_multiply', id, 'Somou em vez de multiplicar', 'conceptual', 'Não associou multiplicação a parcelas iguais.' from app.skills where slug = 'mul.facts';
insert into app.misconceptions(id, skill_id, label, category, description) select 'table_slip', id, 'Tabuada: produto vizinho', 'occasional', 'Resposta é de um produto vizinho na tabuada.' from app.skills where slug = 'mul.facts';
insert into app.misconceptions(id, skill_id, label, category, description) select 'forgot_carry_mul', id, 'Esqueceu de levar na multiplicação', 'procedural', 'Multiplicou dígito a dígito sem transportar.' from app.skills where slug = 'mul.multi';
insert into app.misconceptions(id, skill_id, label, category, description) select 'forgot_shift_zero', id, 'Não deslocou a casa na multiplicação por dezena', 'procedural', 'Somou os produtos parciais sem o zero do deslocamento.' from app.skills where slug = 'mul.multi';
insert into app.misconceptions(id, skill_id, label, category, description) select 'divide_wrong_operation', id, 'Trocou a divisão por outra operação', 'conceptual', 'Usou subtração ou multiplicação em vez de repartir/inverter a multiplicação.' from app.skills where slug = 'div.facts';
insert into app.misconceptions(id, skill_id, label, category, description) select 'ignore_remainder', id, 'Ignorou o resto', 'conceptual', 'Apresentou só o quociente.' from app.skills where slug = 'div.algorithm';
insert into app.misconceptions(id, skill_id, label, category, description) select 'remainder_too_big', id, 'Resto maior que o divisor', 'procedural', 'Não percebeu que ainda cabia mais uma vez o divisor.' from app.skills where slug = 'div.algorithm';
insert into app.misconceptions(id, skill_id, label, category, description) select 'multiple_divisor_confusion', id, 'Confundiu múltiplo com divisor', 'conceptual', 'Escolheu um múltiplo comum quando se pedia divisor comum.' from app.skills where slug = 'factors';
insert into app.misconceptions(id, skill_id, label, category, description) select 'not_greatest', id, 'Parou num divisor comum que não é o maior', 'procedural', 'Encontrou um divisor comum, mas não o maior.' from app.skills where slug = 'factors';
insert into app.misconceptions(id, skill_id, label, category, description) select 'swap_num_den', id, 'Trocou numerador e denominador', 'conceptual', 'Escreveu partes do todo / partes pintadas ao contrário.' from app.skills where slug = 'frac.id';
insert into app.misconceptions(id, skill_id, label, category, description) select 'count_unshaded', id, 'Contou as partes não pintadas', 'conceptual', 'Representou o que falta em vez do que foi destacado.' from app.skills where slug = 'frac.id';
insert into app.misconceptions(id, skill_id, label, category, description) select 'part_to_part', id, 'Comparou parte com parte (não com o todo)', 'conceptual', 'Usou pintadas/não pintadas em vez de pintadas/total.' from app.skills where slug = 'frac.id';
insert into app.misconceptions(id, skill_id, label, category, description) select 'bigger_denominator_bigger', id, 'Acha que denominador maior = fração maior', 'conceptual', 'Usa o tamanho do denominador como se fosse número natural.' from app.skills where slug = 'frac.compare';
insert into app.misconceptions(id, skill_id, label, category, description) select 'compare_numerators_only', id, 'Compara só os numeradores', 'conceptual', 'Ignora que as partes têm tamanhos diferentes.' from app.skills where slug = 'frac.compare';
insert into app.misconceptions(id, skill_id, label, category, description) select 'add_same_to_both', id, 'Soma o mesmo valor a numerador e denominador', 'conceptual', 'Pensa que equivalência é "somar o mesmo número" em cima e embaixo.' from app.skills where slug = 'frac.equiv';
insert into app.misconceptions(id, skill_id, label, category, description) select 'multiply_num_only', id, 'Multiplica só o numerador', 'procedural', 'Altera um termo só e perde a proporção.' from app.skills where slug = 'frac.equiv';
insert into app.misconceptions(id, skill_id, label, category, description) select 'divide_only_numerator', id, 'Dividiu só o numerador', 'procedural', 'Simplificou apenas em cima.' from app.skills where slug = 'frac.simplify';
insert into app.misconceptions(id, skill_id, label, category, description) select 'subtract_to_simplify', id, 'Subtraiu o mesmo valor dos dois termos', 'conceptual', 'Usou subtração no lugar da divisão pelo fator comum.' from app.skills where slug = 'frac.simplify';
insert into app.misconceptions(id, skill_id, label, category, description) select 'partial_simplify', id, 'Simplificou só parcialmente', 'procedural', 'Dividiu por um fator comum, mas não pelo maior.' from app.skills where slug = 'frac.simplify';
insert into app.misconceptions(id, skill_id, label, category, description) select 'add_denominators', id, 'Somou também os denominadores', 'conceptual', 'Não percebeu que o denominador indica o tamanho da parte e não muda.' from app.skills where slug = 'frac.add.same';
insert into app.misconceptions(id, skill_id, label, category, description) select 'add_num_and_den', id, 'Somou numeradores e denominadores diretamente', 'conceptual', 'Ex.: 1/2 + 1/3 = 2/5.' from app.skills where slug = 'frac.add.diff';
insert into app.misconceptions(id, skill_id, label, category, description) select 'common_den_not_converted', id, 'Achou o denominador comum mas não converteu os numeradores', 'procedural', 'Somou numeradores originais sobre o novo denominador.' from app.skills where slug = 'frac.add.diff';
insert into app.misconceptions(id, skill_id, label, category, description) select 'wrong_operation', id, 'Escolheu a operação errada', 'text_interpretation', 'Não relacionou a situação à operação correspondente.' from app.skills where slug = 'prob.interpret';
insert into app.misconceptions(id, skill_id, label, category, description) select 'keyword_trap', id, 'Guiou-se por palavra-chave', 'text_interpretation', 'Escolheu a operação pela palavra ("mais", "ganhou") em vez da situação.' from app.skills where slug = 'prob.interpret';
insert into app.misconceptions(id, skill_id, label, category, description) select 'one_step_only', id, 'Resolveu só uma etapa', 'text_interpretation', 'Parou depois da primeira conta.' from app.skills where slug = 'prob.multi';
insert into app.misconceptions(id, skill_id, label, category, description) select 'wrong_order', id, 'Ordem das etapas trocada', 'text_interpretation', 'Aplicou as operações em ordem que não corresponde à história.' from app.skills where slug = 'prob.multi';
insert into app.misconceptions(id, skill_id, label, category, description) select 'fraction_of_quantity_error', id, 'Erro ao calcular fração de uma quantidade', 'conceptual', 'Não relacionou "fração de" a dividir e multiplicar.' from app.skills where slug = 'prob.frac';
insert into app.misconceptions(id, skill_id, label, category, description) select 'pt_literal_skim', id, 'Respondeu sem localizar no texto', 'text_interpretation', 'Escolheu opção plausível que não está escrita no texto.' from app.skills where slug = 'pt.read.literal';
insert into app.misconceptions(id, skill_id, label, category, description) select 'pt_over_infer', id, 'Inferência sem apoio no texto', 'text_interpretation', 'Concluiu algo que o texto não permite.' from app.skills where slug = 'pt.read.infer';
insert into app.misconceptions(id, skill_id, label, category, description) select 'pt_agree_noun', id, 'Concordância nominal', 'conceptual', 'Não ajustou gênero/número entre artigo, substantivo e adjetivo.' from app.skills where slug = 'pt.gram.agree';
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('off_by_one', 1, 'passo_a_passo', 'Confira contando', '["Sua resposta ficou perto — confira: conte nos dedos ou numa reta numérica e verifique se não parou um passo antes ou depois."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('forgot_carry', 1, 'passo_a_passo', 'Quando a coluna passa de 9', '["Some a coluna da direita (unidades). Se der 10 ou mais, escreva só o dígito das unidades e leve o dez para a coluna seguinte.","Na próxima coluna, some também o que veio \"de carona\"."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('forgot_carry', 2, 'visual', 'Caixas de 10', '["Imagine 10 cubinhos soltos: eles formam uma barra de 10. Ao passar de 9 unidades, troque 10 cubinhos por 1 barra e coloque a barra na coluna das dezenas."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('swap_operands', 1, 'passo_a_passo', 'Ordem importa na subtração', '["Em 12 − 5, você começa em 12 e tira 5. Não dá para \"tirar 12 de 5\". Escreva sempre o maior primeiro e confira com a soma: 7 + 5 = 12."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('swap_operands', 2, 'historia', 'História das figurinhas', '["Você tem 12 figurinhas e dá 5. Quantas restam? Contar o que sobra mostra que o resultado é 7, não −7."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('smaller_from_larger', 1, 'passo_a_passo', 'Quando falta na coluna', '["Se o número de cima é menor que o de baixo, peça 1 dezena emprestada à coluna vizinha: ela vira 10 unidades. Ex.: 52 − 27: 12 − 7 = 5; depois 4 − 2 = 2 → 25."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('smaller_from_larger', 2, 'visual', 'Trocar uma barra por 10 cubinhos', '["52 = 5 barras e 2 cubinhos. Para tirar 7 cubinhos, desmonte 1 barra em 10 cubinhos: agora são 4 barras e 12 cubinhos."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('borrow_slip', 1, 'passo_a_passo', 'Conferir com a soma', '["Depois de subtrair, some o resultado ao número de baixo: deve voltar ao número de cima. Se não voltar, revise o empréstimo."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_instead_of_multiply', 1, 'visual', 'Grupos iguais', '["4 × 3 significa 4 grupos de 3: 3 + 3 + 3 + 3 = 12. Desenhe os grupos e conte."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_instead_of_multiply', 2, 'passo_a_passo', 'Multiplicar é somar parcelas iguais', '["Reescreva a multiplicação como soma repetida e some. Depois memorize os resultados na tabuada."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('table_slip', 1, 'passo_a_passo', 'Apoie-se em um produto que você sabe', '["7 × 6: se 7 × 5 = 35, então 7 × 6 = 35 + 7 = 42."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('forgot_carry_mul', 1, 'passo_a_passo', 'Levar também na multiplicação', '["26 × 3: 6 × 3 = 18 → escreva 8 e leve 1; 2 × 3 = 6, mais 1 que veio = 7 → 78."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('forgot_shift_zero', 1, 'passo_a_passo', 'O zero que "desliza"', '["Ao multiplicar pelas dezenas, a linha começa com um zero (ou uma casa vazia): você está multiplicando por 10, 20, 30… Só depois some as linhas."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('divide_wrong_operation', 1, 'historia', 'Repartir em partes iguais', '["24 balas para 6 amigos: cada um recebe quantas? Pense \"6 vezes quanto dá 24?\" → 4. Dividir é o inverso de multiplicar."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('divide_wrong_operation', 2, 'passo_a_passo', 'Use a tabuada ao contrário', '["Para 24 ÷ 6, procure na tabuada do 6 o número que chega a 24."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('ignore_remainder', 1, 'passo_a_passo', 'O que sobra também conta', '["47 ÷ 5: cabem 9 grupos de 5 (45) e sobram 2. Escrevemos \"9 resto 2\". Confira: 9 × 5 + 2 = 47."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('remainder_too_big', 1, 'passo_a_passo', 'O resto é menor que o divisor', '["Se o resto é igual ou maior que o divisor, ainda dá para formar mais um grupo. Tente de novo com um quociente maior."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('multiple_divisor_confusion', 1, 'contraexemplo', 'Divisor × múltiplo', '["Divisores \"cabem dentro\" do número (6 divide 12). Múltiplos \"vão além\" (24 é múltiplo de 12). Faça a pergunta: o número divide os dois, sem sobrar?"]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('not_greatest', 1, 'passo_a_passo', 'Liste todos os divisores', '["Escreva os divisores de cada número, marque os comuns e escolha o maior."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('swap_num_den', 1, 'visual', 'Quem é quem', '["O denominador (embaixo) diz em quantas partes iguais o todo foi dividido. O numerador (em cima) diz quantas partes estamos considerando. 3 de 8 partes → 3/8."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('swap_num_den', 2, 'historia', 'A pizza', '["A pizza tem 8 fatias (embaixo). Você comeu 3 (em cima). Lemos \"três oitavos\"."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('count_unshaded', 1, 'visual', 'Conte o que está pintado', '["A fração representa as partes destacadas (pintadas). As não pintadas representam a fração complementar."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('part_to_part', 1, 'visual', 'Sempre compare com o todo', '["O denominador é o total de partes iguais — pintadas e não pintadas juntas."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('bigger_denominator_bigger', 1, 'visual', 'Pizzas do mesmo tamanho', '["Divida duas pizzas iguais: uma em 3 fatias, outra em 5. As fatias de 1/3 são maiores que as de 1/5. Quanto mais partes, menores elas são."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('bigger_denominator_bigger', 2, 'contraexemplo', 'Teste com 1/2 e 1/10', '["Prefere 1/2 ou 1/10 de chocolate? Mesmo \"10 > 2\", 1/2 é muito mais."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('compare_numerators_only', 1, 'passo_a_passo', 'Mesmo tamanho de parte primeiro', '["Para comparar, deixe as frações com o mesmo denominador (partes do mesmo tamanho). Depois compare os numeradores."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_same_to_both', 1, 'visual', 'Equivalência é multiplicar (ou dividir) os dois termos', '["1/2 → 2/4 → 3/6: o denominador dobra, triplica, e o numerador acompanha. Somar o mesmo valor muda o tamanho da fração."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_same_to_both', 2, 'contraexemplo', 'Teste: 1/2 e 2/3', '["Se somar 1 em cima e embaixo valesse, 1/2 = 2/3. Mas 1/2 é metade e 2/3 é mais que a metade."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('multiply_num_only', 1, 'passo_a_passo', 'Os dois termos juntos', '["Para manter o valor, multiplique numerador e denominador pelo mesmo número."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('divide_only_numerator', 1, 'passo_a_passo', 'Dividir em cima e embaixo', '["Simplificar é dividir numerador e denominador pelo mesmo número: 6/8 ÷ 2 = 3/4."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('subtract_to_simplify', 1, 'contraexemplo', 'Subtrair muda o valor', '["6/8 − 2 em cima e embaixo daria 4/6, que não é a mesma quantidade. Divisão mantém o valor."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('partial_simplify', 1, 'passo_a_passo', 'Continue até não dar mais', '["Depois de simplificar, veja se ainda há divisor comum. 12/18 → 6/9 → 2/3."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_denominators', 1, 'visual', 'Fatias do mesmo tamanho', '["1/5 + 2/5: são fatias de quinto. Juntar 1 fatia e 2 fatias dá 3 fatias de quinto = 3/5. O tamanho da fatia (denominador) não muda."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_denominators', 2, 'historia', 'Barra de chocolate', '["Uma barra em 5 pedaços: você come 1 e depois mais 2. Comeu 3 pedaços de 5."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_num_and_den', 1, 'visual', 'Fatias de tamanhos diferentes', '["1/2 e 1/3 são fatias de tamanhos diferentes e não dá para somá-las direto. Troque ambas por sextos: 3/6 + 2/6 = 5/6."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_num_and_den', 2, 'contraexemplo', 'Teste simples', '["Se 1/2 + 1/3 fosse 2/5, a soma seria menor que 1/2 (2/5 = 0,4), mas juntar mais um pedaço não pode diminuir a quantidade."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_num_and_den', 3, 'passo_a_passo', 'Receita', '["1) ache um denominador comum; 2) converta cada fração; 3) some os numeradores; 4) mantenha o denominador; 5) simplifique."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('common_den_not_converted', 1, 'passo_a_passo', 'Converter também o numerador', '["1/2 = 3/6 (multiplicou por 3 em cima e embaixo). Só depois some os numeradores."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('wrong_operation', 1, 'historia', 'Qual é a história?', '["Juntar → somar. Tirar/comparar → subtrair. Grupos iguais → multiplicar. Repartir igualmente → dividir. Conte a história com suas palavras antes de escolher a conta."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('keyword_trap', 1, 'contraexemplo', 'Palavra-pista pode enganar', '["\"4 a mais que João\" não significa somar a 4 se já sabemos quanto tem o outro. Desenhe quem tem mais e quem tem menos."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('one_step_only', 1, 'passo_a_passo', 'Releia a pergunta', '["Sublinhe o que a pergunta final pede. Se ainda faltam informações, há outra etapa."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('wrong_order', 1, 'passo_a_passo', 'Siga a história na ordem', '["Escreva cada acontecimento como uma conta, na ordem em que acontece."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('fraction_of_quantity_error', 1, 'passo_a_passo', '1/4 de 20', '["O denominador diz em quantas partes dividir (20 ÷ 4 = 5). O numerador diz quantas dessas partes pegar (1 × 5 = 5)."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_literal_skim', 1, 'passo_a_passo', 'Volte ao texto', '["Procure a frase que responde à pergunta e sublinhe-a antes de escolher a alternativa."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_over_infer', 1, 'passo_a_passo', 'Do texto, não do palpite', '["Uma inferência precisa de pelo menos uma pista no texto. Qual frase apoia sua resposta?"]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_agree_noun', 1, 'passo_a_passo', 'Combine artigo, substantivo e adjetivo', '["Se o substantivo está no feminino plural, os acompanhantes também: \"as casas pequenas\"."]'::jsonb);
